package net.civeira.phylax.feature.access.oauthclient.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.access.oauthclient.domain.OauthClient;
import net.civeira.phylax.feature.access.oauthclient.domain.valueobject.AuthorizationDetailsTypesVO;

class AuthorizationDetailsTypesValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of authorization details types of oauth client")
  void test_authorization_details_types_value_holder_assign_plain_value() {
    Object holder = new Object();
    AuthorizationDetailsTypesValueHolder<Object> value =
        new AuthorizationDetailsTypesValueHolder<>(holder);
    Assertions.assertSame(holder, value.authorizationDetailsTypes("one"),
        "Setters must return the holder");
    Assertions.assertTrue(value.getAuthorizationDetailsTypesValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals("one", value.getAuthorizationDetailsTypes().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.authorizationDetailsTypesNull(),
        "Setters must return the holder");
    Assertions.assertTrue(value.getAuthorizationDetailsTypesValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getAuthorizationDetailsTypes().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of authorization details types of oauth client")
  void test_authorization_details_types_value_holder_assign_value_object() {
    Object holder = new Object();
    AuthorizationDetailsTypesValueHolder<Object> value =
        new AuthorizationDetailsTypesValueHolder<>(holder);
    AuthorizationDetailsTypesVO vo = AuthorizationDetailsTypesVO.from("one");
    Assertions.assertFalse(value.getAuthorizationDetailsTypesValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.authorizationDetailsTypes(vo),
        "Setters must return the holder");
    Assertions.assertSame(vo, value.getAuthorizationDetailsTypesValue().orElseThrow());
    Assertions.assertSame(holder, value.authorizationDetailsTypes(Optional.empty()));
    Assertions.assertFalse(value.getAuthorizationDetailsTypesValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.authorizationDetailsTypes(Optional.of(vo)));
    Assertions.assertSame(vo, value.getAuthorizationDetailsTypesValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of authorization details types of oauth client against the original")
  void test_authorization_details_types_value_holder_read() {
    Object holder = new Object();
    AuthorizationDetailsTypesValueHolder<Object> value =
        new AuthorizationDetailsTypesValueHolder<>(holder);
    AuthorizationDetailsTypesVO vo = AuthorizationDetailsTypesVO.from("one");
    AuthorizationDetailsTypesVO other = AuthorizationDetailsTypesVO.from("one");
    OauthClient original = Mockito.mock(OauthClient.class);
    Mockito.when(original.getAuthorizationDetailsTypesValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readAuthorizationDetailsTypes(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readAuthorizationDetailsTypes(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.authorizationDetailsTypes(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readAuthorizationDetailsTypes(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readAuthorizationDetailsTypes(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of authorization details types of oauth client")
  void test_authorization_details_types_value_holder_unset() {
    Object holder = new Object();
    AuthorizationDetailsTypesValueHolder<Object> value =
        new AuthorizationDetailsTypesValueHolder<>(holder);
    AuthorizationDetailsTypesVO vo = AuthorizationDetailsTypesVO.from("one");
    value.authorizationDetailsTypes(vo);
    Assertions.assertSame(holder,
        value.unsetAuthorizationDetailsTypesIfMatches("authorizationDetailsTypes_other"));
    Assertions.assertTrue(value.getAuthorizationDetailsTypesValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder,
        value.unsetAuthorizationDetailsTypesIfMatches("authorizationDetailsTypes"));
    Assertions.assertFalse(value.getAuthorizationDetailsTypesValue().isPresent(),
        "The field name must clear the value");
    value.authorizationDetailsTypes(vo);
    Assertions.assertSame(holder, value.unsetAuthorizationDetailsTypes());
    Assertions.assertFalse(value.getAuthorizationDetailsTypesValue().isPresent(),
        "Unset must clear the value");
  }
}
